Singularity.Algebra.IsGradingProj.eq_zer.type:
∀ {R : Type u} [inst : CommRing R] {N : Type v} [inst_1 : AddCommGroup N] [inst_2 : Module R N] {𝒩 : ℕ → Submodule R N}
  {π : ℕ → N →ₗ[R] N},
  Singularity.Algebra.IsGradingProj 𝒩 π → ∀ {n : ℕ} {y : N}, y ∈ ⨆ m, ⨆ (_ : m ≠ n), 𝒩 m → (π n) y = 0

Singularity.Algebra.IsGradingProj.proj_m.type:
∀ {R : Type u} [inst : CommRing R] {S : Type w} [inst_1 : CommRing S] [inst_2 : Algebra R S] {N : Type v}
  [inst_3 : AddCommGroup N] [inst_4 : Module S N] [inst_5 : Module R N] [IsScalarTower R S N] {𝒩 : ℕ → Submodule R N}
  {π : ℕ → N →ₗ[R] N} (μ : N →ₗ[S] N),
  Singularity.Algebra.IsGradingProj 𝒩 π →
    ⨆ n, 𝒩 n = ⊤ → (∀ (n : ℕ), ∀ y ∈ 𝒩 n, μ y ∈ 𝒩 (n + 1)) → ∀ (n : ℕ) (w : N), (π n) (μ w) ∈ μ.range

