Singularity.Algebra.exists_eq_span_singl.type:
∀ {R : Type u} [inst : CommRing R] [inst_1 : IsRegularLocalRing R] (P : Ideal R) [IsRegularLocalRing (R ⧸ P)],
  ringKrullDim (R ⧸ P) + 1 = ringKrullDim R →
    ∃ x ∈ IsLocalRing.maximalIdeal R, x ∉ IsLocalRing.maximalIdeal R ^ 2 ∧ P = Ideal.span {x}

Singularity.Algebra.grGen_smul.type:
∀ {R : Type u} [inst : CommRing R] {I : Ideal R} {M : Type v} [inst_1 : AddCommGroup M] [inst_2 : Module R M] {r : ℕ}
  {x : Fin r → R} (hI : I = Ideal.span (Set.range x)) (i : Fin r) (z : Singularity.Algebra.GrMod I M),
  Singularity.Algebra.grGen M hI i • z = (Singularity.Algebra.grShift ⋯) z

Singularity.Algebra.grMulSum_apply.type:
∀ {R : Type u} [inst : CommRing R] {I : Ideal R} {M : Type v} [inst_1 : AddCommGroup M] [inst_2 : Module R M] {r : ℕ}
  {x : Fin r → R} (hI : I = Ideal.span (Set.range x)) (n : ℕ) (f : Fin r → Singularity.Algebra.grPiece I M n),
  (Singularity.Algebra.grMulSum hI n) f = ∑ i, (Singularity.Algebra.grMul ⋯ n) (f i)

