Singularity.pointChart_eq_X_pow_mul_char.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] (j : σ) (t : σ → k) {m : ℕ}
  {f : MvPolynomial σ k},
  ↑m ≤ Singularity.ord f → (Singularity.pointChart j t) f = MvPolynomial.X j ^ m * Singularity.chartTransform j t m f

Singularity.pointChart_of_isHomogeneous.type:
∀ {σ : Type u_1} {k : Type u_2} [inst : Field k] [inst_1 : DecidableEq σ] (j : σ) (t : σ → k) {m : ℕ}
  {p : MvPolynomial σ k},
  p.IsHomogeneous m → (Singularity.pointChart j t) p = MvPolynomial.X j ^ m * (Singularity.chartRest j t) p
